class Solution {
public:
    string pushDominoes(string dominoes) {
        string s = "L" + dominoes + "R";
        string res = "";
        int i = 0, n = s.length();
        for (int j = 1; j < n; j++) {
            if (s[j] == '.') continue;
            int mid = j - i - 1;
            if (i > 0) res += s[i];
            if (s[i] == s[j]) {
                res += string(mid, s[i]);
            } else if (s[i] == 'L' && s[j] == 'R') {
                res += string(mid, '.');
            } else {
                res += string(mid / 2, 'R') + ((mid % 2) ? "." : "") + string(mid / 2, 'L');
            }
            i = j;
        }
        return res;
    }
};

class Solution {
    public String pushDominoes(String dominoes) {
        String s = "L" + dominoes + "R";
        StringBuilder res = new StringBuilder();
        int i = 0, n = s.length();
        for (int j = 1; j < n; j++) {
            if (s.charAt(j) == '.') continue;
            int mid = j - i - 1;
            if (i > 0) res.append(s.charAt(i));
            if (s.charAt(i) == s.charAt(j)) {
                for (int k = 0; k < mid; k++) res.append(s.charAt(i));
            } else if (s.charAt(i) == 'L' && s.charAt(j) == 'R') {
                for (int k = 0; k < mid; k++) res.append('.');
            } else {
                for (int k = 0; k < mid / 2; k++) res.append('R');
                if (mid % 2 == 1) res.append('.');
                for (int k = 0; k < mid / 2; k++) res.append('L');
            }
            i = j;
        }
        return res.toString();
    }
}

var pushDominoes = function(dominoes) {
    const s = 'L' + dominoes + 'R';
    const res = [];
    let i = 0;
    for (let j = 1; j < s.length; j++) {
        if (s[j] === '.') continue;
        const mid = j - i - 1;
        if (i > 0) res.push(s[i]);
        if (s[i] === s[j]) {
            res.push(s[i].repeat(mid));
        } else if (s[i] === 'L' && s[j] === 'R') {
            res.push('.'.repeat(mid));
        } else {
            res.push('R'.repeat(Math.floor(mid / 2)) + ((mid % 2) ? '.' : '') + 'L'.repeat(Math.floor(mid / 2)));
        }
        i = j;
    }
    return res.join('');
};
